<?php
session_start();
require_once '../includes/config.php';
if(empty($_SESSION['rider_logged_in']) || $_SESSION['rider_logged_in']!==true){header('Location:rider-login.php');exit;}
$riderId=(int)($_SESSION['rider_id']??0);if($riderId<1){session_destroy();header('Location:rider-login.php');exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function hasTable($db,$t){$t=$db->real_escape_string($t);$r=$db->query("SHOW TABLES LIKE '$t'");return $r&&$r->num_rows>0;}
function notifyCustomer($db,$uid,$title,$message,$type,$oid){if(!$uid||!hasTable($db,'notifications'))return;$s=$db->prepare("INSERT INTO notifications(user_id,role,title,message,type,reference_id) VALUES(?,'customer',?,?,?,?)");if($s){$s->bind_param('isssi',$uid,$title,$message,$type,$oid);$s->execute();$s->close();}}
$r=['full_name'=>'Rider','phone'=>'','vehicle_type'=>'Bike','bike_number'=>'','status'=>'pending'];
$s=$conn->prepare('SELECT full_name,phone,vehicle_type,bike_number,status FROM riders WHERE id=? LIMIT 1');if($s){$s->bind_param('i',$riderId);$s->execute();$x=$s->get_result()->fetch_assoc();$s->close();if($x)$r=array_merge($r,$x);}
$approved=in_array(strtolower(trim($r['status'])),['active','approved'],true);
$conn->query("CREATE TABLE IF NOT EXISTS rider_locations(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rider_id INT NOT NULL,latitude DECIMAL(10,7) NOT NULL,longitude DECIMAL(10,7) NOT NULL,accuracy DECIMAL(10,2) NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(rider_id,updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$conn->query("CREATE TABLE IF NOT EXISTS rider_deliveries(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rider_id INT NOT NULL,order_id INT NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'accepted',accepted_at DATETIME NULL,picked_up_at DATETIME NULL,delivered_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY rider_order(rider_id,order_id),INDEX(order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$cols=[];$q=$conn->query('SHOW COLUMNS FROM orders');if($q)while($c=$q->fetch_assoc())$cols[]=$c['Field'];
$riderCol=null;foreach(['rider_id','delivery_rider_id','assigned_rider_id'] as $c)if(in_array($c,$cols,true)){$riderCol=$c;break;}
$statusCol=null;foreach(['order_status','status'] as $c)if(in_array($c,$cols,true)){$statusCol=$c;break;}
if(!$riderCol||!$statusCol)die('Orders table needs rider and status columns.');
if(($_GET['ajax']??'')==='location'&&$_SERVER['REQUEST_METHOD']==='POST'){$lat=filter_var($_POST['latitude']??null,FILTER_VALIDATE_FLOAT);$lng=filter_var($_POST['longitude']??null,FILTER_VALIDATE_FLOAT);$acc=filter_var($_POST['accuracy']??null,FILTER_VALIDATE_FLOAT);header('Content-Type:application/json');if($lat===false||$lng===false){echo json_encode(['ok'=>false]);exit;}$s=$conn->prepare('INSERT INTO rider_locations(rider_id,latitude,longitude,accuracy) VALUES(?,?,?,?)');$s->bind_param('iddd',$riderId,$lat,$lng,$acc);$ok=$s->execute();$s->close();echo json_encode(['ok'=>$ok]);exit;}
$msg='';$type='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['delivery_action'])){$action=$_POST['delivery_action'];$oid=(int)($_POST['order_id']??0);$allowed=['accept','picked_up','out_for_delivery','delivered'];
 if(!$approved){$msg='Your rider account is not approved yet.';$type='error';}
 elseif(!$oid||!in_array($action,$allowed,true)){$msg='Invalid delivery request.';$type='error';}
 else{$conn->begin_transaction();try{$s=$conn->prepare("SELECT * FROM orders WHERE id=? LIMIT 1 FOR UPDATE");$s->bind_param('i',$oid);$s->execute();$o=$s->get_result()->fetch_assoc();$s->close();if(!$o)throw new Exception('Order not found.');$cur=strtolower(trim($o[$statusCol]));$assigned=(int)($o[$riderCol]??0);
  if($action==='accept'){$new='rider_assigned';if($cur!=='preparing')throw new Exception('Only Preparing orders can be accepted.');if($assigned&&$assigned!==$riderId)throw new Exception('This order was already accepted by another rider.');$s=$conn->prepare("UPDATE orders SET `$riderCol`=?,`$statusCol`=? WHERE id=? AND (`$riderCol` IS NULL OR `$riderCol`=0) AND LOWER(TRIM(`$statusCol`))='preparing' LIMIT 1");$s->bind_param('isi',$riderId,$new,$oid);$s->execute();if($s->affected_rows!==1)throw new Exception('This order was already taken.');$s->close();$s=$conn->prepare("INSERT INTO rider_deliveries(rider_id,order_id,status,accepted_at) VALUES(?,?, 'accepted',NOW()) ON DUPLICATE KEY UPDATE status='accepted',accepted_at=NOW()");$s->bind_param('ii',$riderId,$oid);$s->execute();$s->close();notifyCustomer($conn,(int)($o['user_id']??0),'Rider assigned','A rider has accepted order #'.$oid.'. Rider information and live location are now available.','rider_assigned',$oid);$msg='Delivery accepted. You are assigned to order #'.$oid.'.';}
  else{if($assigned!==$riderId)throw new Exception('This order is not assigned to you.');if($action==='picked_up'){if($cur!=='rider_assigned')throw new Exception('Order must be Rider Assigned first.');$new='picked_up';$s=$conn->prepare("UPDATE orders SET `$statusCol`=? WHERE id=? AND `$riderCol`=? LIMIT 1");$s->bind_param('sii',$new,$oid,$riderId);$s->execute();$s->close();$s=$conn->prepare("UPDATE rider_deliveries SET status='picked_up',picked_up_at=NOW() WHERE rider_id=? AND order_id=?");$s->bind_param('ii',$riderId,$oid);$s->execute();$s->close();notifyCustomer($conn,(int)($o['user_id']??0),'Order picked up','Your order #'.$oid.' has been picked up by the rider.','order_picked_up',$oid);$msg='Order marked as Picked Up.';}
   elseif($action==='out_for_delivery'){if($cur!=='picked_up')throw new Exception('Pick up the order before starting delivery.');$new='out_for_delivery';$s=$conn->prepare("UPDATE orders SET `$statusCol`=? WHERE id=? AND `$riderCol`=? LIMIT 1");$s->bind_param('sii',$new,$oid,$riderId);$s->execute();$s->close();$s=$conn->prepare("UPDATE rider_deliveries SET status='out_for_delivery' WHERE rider_id=? AND order_id=?");$s->bind_param('ii',$riderId,$oid);$s->execute();$s->close();notifyCustomer($conn,(int)($o['user_id']??0),'Order is on the way','Your order #'.$oid.' is now out for delivery.','out_for_delivery',$oid);$msg='Order is now Out for Delivery.';}
   else{if(!in_array($cur,['out_for_delivery','picked_up'],true))throw new Exception('Order is not ready to be delivered.');$new='delivered';$s=$conn->prepare("UPDATE orders SET `$statusCol`=? WHERE id=? AND `$riderCol`=? LIMIT 1");$s->bind_param('sii',$new,$oid,$riderId);$s->execute();$s->close();$s=$conn->prepare("UPDATE rider_deliveries SET status='delivered',delivered_at=NOW() WHERE rider_id=? AND order_id=?");$s->bind_param('ii',$riderId,$oid);$s->execute();$s->close();notifyCustomer($conn,(int)($o['user_id']??0),'Order delivered','Your order #'.$oid.' has been delivered successfully.','delivered',$oid);$msg='Order marked as Delivered.';}}
  $conn->commit();$type='success';}catch(Throwable $e){$conn->rollback();$msg=$e->getMessage();$type='error';}}
}
$available=[];$s=$conn->prepare("SELECT o.*,u.full_name customer_name,u.phone customer_phone FROM orders o LEFT JOIN users u ON u.id=o.user_id WHERE LOWER(TRIM(o.`$statusCol`))='preparing' AND (o.`$riderCol` IS NULL OR o.`$riderCol`=0) ORDER BY o.id DESC");if($s){$s->execute();$rs=$s->get_result();while($x=$rs->fetch_assoc())$available[]=$x;$s->close();}
$active=[];$s=$conn->prepare("SELECT o.*,u.full_name customer_name,u.phone customer_phone FROM orders o LEFT JOIN users u ON u.id=o.user_id WHERE o.`$riderCol`=? AND LOWER(TRIM(o.`$statusCol`)) NOT IN('delivered','completed','cancelled','rejected') ORDER BY o.id DESC");if($s){$s->bind_param('i',$riderId);$s->execute();$rs=$s->get_result();while($x=$rs->fetch_assoc())$active[]=$x;$s->close();}
$history=[];$earnings=0;$s=$conn->prepare("SELECT o.*,u.full_name customer_name FROM orders o LEFT JOIN users u ON u.id=o.user_id WHERE o.`$riderCol`=? AND LOWER(TRIM(o.`$statusCol`)) IN('delivered','completed') ORDER BY o.id DESC LIMIT 30");if($s){$s->bind_param('i',$riderId);$s->execute();$rs=$s->get_result();while($x=$rs->fetch_assoc()){$history[]=$x;$earnings+=(float)($x['delivery_fee']??0);}$s->close();}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rider Orders | Humsafar</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>
*{box-sizing:border-box}body{margin:0;background:#f7f8fa;color:#222;font-family:Segoe UI,Arial,sans-serif;font-size:15px}.page{margin-left:220px;padding:30px 34px;min-height:100vh}.head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:25px}.eyebrow{font-size:12px;font-weight:900;letter-spacing:1px;color:#ef003c;text-transform:uppercase}.title{font-size:34px;margin:5px 0;font-weight:900}.sub{color:#777;margin:0}.profile{background:#fff;border:1px solid #e8e8e8;border-radius:13px;padding:12px 17px;text-align:right}.profile small{display:block;color:#777;margin-top:4px}.flash{padding:15px 18px;border-radius:12px;margin-bottom:20px;font-weight:700}.success{background:#eaf9ef;border:1px solid #c8ecd4;color:#18703a}.error{background:#fff0f3;border:1px solid #ffd1db;color:#b00030}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin-bottom:28px}.stat{background:#fff;border:1px solid #e8e8e8;border-radius:16px;padding:19px}.stat i{float:right;color:#ef003c}.stat small{display:block;color:#777;font-weight:700}.stat strong{display:block;font-size:27px;margin-top:6px}.section{margin:28px 0}.section h2{font-size:22px;margin:0 0 15px}.card{background:#fff;border:1px solid #e7e7e7;border-radius:17px;overflow:hidden;margin-bottom:17px;box-shadow:0 5px 18px #00000008}.cardhead{padding:19px 22px;border-bottom:1px solid #eee;display:flex;justify-content:space-between;gap:10px}.order{font-size:20px;font-weight:900}.date{font-size:13px;color:#888;margin-top:4px}.badge{background:#fff0f5;color:#d00037;border-radius:99px;padding:8px 13px;font-size:12px;font-weight:900;height:max-content}.green{background:#eaf9ef;color:#18703a}.body{padding:22px;display:grid;grid-template-columns:1fr 330px;gap:22px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.box{background:#fafafa;border:1px solid #eee;border-radius:12px;padding:14px}.box small{display:block;color:#888;text-transform:uppercase;font-size:10px;font-weight:800}.box strong{display:block;margin-top:5px}.notice{margin-top:16px;padding:15px;border-radius:12px;background:#f5faff;border:1px solid #d8eaf6;color:#486675;line-height:1.55}.actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:16px}.btn{border:0;border-radius:10px;padding:12px 16px;font-weight:900;cursor:pointer}.accept{background:#ef003c;color:#fff}.pickup{background:#fff1dc;color:#875300}.way{background:#eaf6ff;color:#076a9e}.deliver{background:#eaf9ef;color:#18703a}.tracking{background:#f5faff;border:1px solid #d8eaf6;border-radius:13px;padding:17px}.live{color:#09894a;font-weight:900}.gps{margin-top:10px;color:#58717c;font-size:13px}.empty{padding:50px;text-align:center;background:#fff;border:1px dashed #ddd;border-radius:16px;color:#888}.history{width:100%;border-collapse:collapse;background:#fff}.history th,.history td{padding:13px 15px;border-bottom:1px solid #eee;text-align:left}.history th{background:#fafafa;font-size:12px;color:#777}@media(max-width:1050px){.page{margin-left:0}.body{grid-template-columns:1fr}}@media(max-width:750px){.page{padding:18px}.stats{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}.profile{display:none}.actions .btn{width:100%}}@media(max-width:500px){.stats{grid-template-columns:1fr}}
</style></head><body><?php if(file_exists(__DIR__.'/rider-sidebar.php'))include __DIR__.'/rider-sidebar.php'; ?><main class="page"><div class="head"><div><div class="eyebrow">Delivery Partner</div><h1 class="title">Rider Orders</h1><p class="sub">Accept deliveries, update delivery stages and keep your GPS location live.</p></div><div class="profile"><strong><?=h($r['full_name'])?></strong><small><?=h(ucwords($r['status']))?> · <?=h($r['vehicle_type'])?></small></div></div>
<?php if($msg): ?><div class="flash <?=h($type)?>"><i class="fa-solid fa-circle-<?=($type==='success'?'check':'exclamation')?>"></i> <?=h($msg)?></div><?php endif; ?>
<div class="stats"><div class="stat"><i class="fa-solid fa-bell"></i><small>New Deliveries</small><strong><?=count($available)?></strong></div><div class="stat"><i class="fa-solid fa-motorcycle"></i><small>Active Deliveries</small><strong><?=count($active)?></strong></div><div class="stat"><i class="fa-solid fa-circle-check"></i><small>Completed</small><strong><?=count($history)?></strong></div><div class="stat"><i class="fa-solid fa-wallet"></i><small>Delivery Earnings</small><strong>Rs <?=number_format($earnings,0)?></strong></div></div>
<section class="section"><h2><i class="fa-solid fa-bell"></i> New Deliveries</h2><?php if(!$approved): ?><div class="empty"><h3>Account approval required</h3><p>Your rider account must be approved before accepting deliveries.</p></div><?php elseif(!$available): ?><div class="empty"><h3>No new deliveries</h3><p>Restaurant-accepted orders will appear here as <b>Preparing · Rider Needed</b>.</p></div><?php else: foreach($available as $o): ?><article class="card"><div class="cardhead"><div><div class="order">Order #<?=h($o['order_number']??$o['id'])?></div><div class="date">Restaurant accepted · <?=h(date('d M Y, h:i A',strtotime($o['created_at']??'now')))?></div></div><span class="badge">Preparing · Rider Needed</span></div><div class="body"><div><div class="grid"><div class="box"><small>Customer</small><strong><?=h($o['customer_name']??'Customer')?></strong></div><div class="box"><small>Phone</small><strong><?=h($o['customer_phone']??'Not available')?></strong></div><div class="box"><small>Total</small><strong>Rs <?=number_format((float)($o['total']??0),0)?></strong></div></div><div class="notice"><b>New delivery available.</b><br>Accept it to become the assigned rider. The first successful acceptance wins the delivery.</div><form method="post" class="actions"><input type="hidden" name="order_id" value="<?=h($o['id'])?>"><button class="btn accept" name="delivery_action" value="accept"><i class="fa-solid fa-check"></i> Accept Delivery</button></form></div><div class="tracking"><b>After acceptance</b><p>Customer and restaurant will receive your rider information. GPS tracking runs while you have an active delivery.</p></div></div></article><?php endforeach; endif; ?></section>
<section class="section"><h2><i class="fa-solid fa-truck-fast"></i> My Active Deliveries</h2><?php if(!$active): ?><div class="empty">No active delivery assigned to you.</div><?php else: foreach($active as $o): $s=strtolower(trim($o[$statusCol])); ?><article class="card active"><div class="cardhead"><div><div class="order">Order #<?=h($o['order_number']??$o['id'])?></div><div class="date">Customer: <?=h($o['customer_name']??'Customer')?></div></div><span class="badge <?=in_array($s,['delivered','completed'],true)?'green':''?>"><?=h(ucwords(str_replace('_',' ',$s)))?></span></div><div class="body"><div><div class="grid"><div class="box"><small>Customer</small><strong><?=h($o['customer_name']??'Customer')?></strong></div><div class="box"><small>Phone</small><strong><?=h($o['customer_phone']??'Not available')?></strong></div><div class="box"><small>Total</small><strong>Rs <?=number_format((float)($o['total']??0),0)?></strong></div></div><div class="notice"><b>Delivery sequence:</b> Assigned → Picked Up → Out for Delivery → Delivered</div><div class="actions"><?php if($s==='rider_assigned'): ?><form method="post"><input type="hidden" name="order_id" value="<?=h($o['id'])?>"><button class="btn pickup" name="delivery_action" value="picked_up">📦 Mark Picked Up</button></form><?php elseif($s==='picked_up'): ?><form method="post"><input type="hidden" name="order_id" value="<?=h($o['id'])?>"><button class="btn way" name="delivery_action" value="out_for_delivery">🚴 Start Delivery</button></form><?php elseif($s==='out_for_delivery'): ?><form method="post" onsubmit="return confirm('Confirm delivery completed?')"><input type="hidden" name="order_id" value="<?=h($o['id'])?>"><button class="btn deliver" name="delivery_action" value="delivered">✓ Mark Delivered</button></form><?php endif; ?></div></div><div class="tracking"><b>Live GPS</b><p class="live">● GPS tracking active for this delivery.</p><div class="gps" data-gps>Waiting for location permission...</div></div></div></article><?php endforeach; endif; ?></section>
<section class="section"><h2><i class="fa-solid fa-clock-rotate-left"></i> Delivery History</h2><?php if(!$history): ?><div class="empty">No completed deliveries yet.</div><?php else: ?><div style="overflow:auto"><table class="history"><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Total</th><th>Earning</th></tr></thead><tbody><?php foreach($history as $o): ?><tr><td>#<?=h($o['order_number']??$o['id'])?></td><td><?=h($o['customer_name']??'Customer')?></td><td><?=h(date('d M Y',strtotime($o['created_at']??'now')))?></td><td>Rs <?=number_format((float)($o['total']??0),0)?></td><td>Rs <?=number_format((float)($o['delivery_fee']??0),0)?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></main>
<script>
const active=document.querySelectorAll('.active');
function gpsSend(p){const f=new FormData();f.append('latitude',p.coords.latitude);f.append('longitude',p.coords.longitude);f.append('accuracy',p.coords.accuracy||'');fetch('?ajax=location',{method:'POST',body:f,credentials:'same-origin'}).catch(()=>{});document.querySelectorAll('[data-gps]').forEach(e=>e.innerHTML='<b style="color:#09894a">GPS Live</b> · '+p.coords.latitude.toFixed(5)+', '+p.coords.longitude.toFixed(5));}
if(active.length&&navigator.geolocation){navigator.geolocation.watchPosition(gpsSend,()=>document.querySelectorAll('[data-gps]').forEach(e=>e.textContent='GPS permission/location unavailable.'),{enableHighAccuracy:true,maximumAge:5000,timeout:15000});}
setInterval(()=>{if(document.visibilityState==='visible')location.reload();},20000);
</script></body></html>
